@transaction.atomic
def auto_allocate_stock(
    self,
    location: Optional[stock.models.StockLocation] = None,
    exclude_location: Optional[stock.models.StockLocation] = None,
    shipment: Optional['SalesOrderShipment'] = None,
    line_ids: Optional[list] = None,
    **kwargs,
):
    """Automatically allocate stock items against this SalesOrder.

    For each unallocated line item, finds available stock for
    the line's part, filtered and sorted according to the supplied kwargs, then
    creates SalesOrderAllocation records in bulk.

    Arguments:
        location: If provided, only consider stock within this location tree.
        exclude_location: If provided, exclude stock within this location tree.
        shipment: Optional shipment to assign allocations to.
        line_ids: If provided, only allocate against these specific line item PKs.

    Kwargs:
        interchangeable (bool): If True (default), consume stock from multiple
            items/locations to satisfy a line. If False, only allocate when a
            single item can cover the full remaining quantity.
    """
    stock_sort_by = kwargs.get('stock_sort_by', STOCK_SORT_DEFAULT)
    interchangeable = kwargs.get('interchangeable', True)
    serialized_stock = kwargs.get('serialized_stock', SERIALIZED_STOCK_DEFAULT)

    new_allocations = []

    lines = self.lines.all()
    if line_ids:
        lines = lines.filter(pk__in=line_ids)

    for line_item in lines:
        if not line_item.part:
            continue

        if line_item.part.virtual:
            continue

        unallocated = line_item.quantity - line_item.allocated_quantity()

        if unallocated <= 0:
            continue

        available_stock = stock.models.StockItem.objects.filter(
            stock.models.StockItem.IN_STOCK_FILTER, part=line_item.part
        )

        if location:
            sublocations = location.get_descendants(include_self=True)
            available_stock = available_stock.filter(
                location__in=list(sublocations)
            )

        if exclude_location:
            sublocations = exclude_location.get_descendants(include_self=True)
            available_stock = available_stock.exclude(
                location__in=list(sublocations)
            )

        if serialized_stock == 'serialized':
            available_stock = available_stock.filter(
                serial__isnull=False, quantity=1
            ).exclude(serial='')
        elif serialized_stock == 'unserialized':
            available_stock = available_stock.filter(
                Q(serial__isnull=True) | Q(serial='')
            )

        # Handle NULL expiry_date last when sorting by expiry.
        if stock_sort_by == stock.models.StockSortOrder.EXPIRY_SOONEST:
            available_stock = available_stock.order_by(
                F('expiry_date').asc(nulls_last=True)
            )
        else:
            available_stock = available_stock.order_by(stock_sort_by)

        # Allow plugins to filter / reorder the candidate stock items
        available_stock = apply_allocate_mixin(
            'filter_sales_order_allocation', line_item, available_stock, **kwargs
        )

        stock_count = len(available_stock)

        if stock_count == 0:
            continue

        if not interchangeable and stock_count > 1:
            # Only allocate when a single item can fully cover the requirement.
            single = next(
                (
                    s
                    for s in available_stock
                    if s.unallocated_quantity() >= unallocated
                ),
                None,
            )
            if single is None:
                continue
            available_stock = [single]

        for stock_item in available_stock:
            available_qty = stock_item.unallocated_quantity()

            if available_qty <= 0:
                continue

            quantity = min(unallocated, available_qty)

            new_allocations.append(
                SalesOrderAllocation(
                    line=line_item,
                    item=stock_item,
                    quantity=quantity,
                    shipment=shipment,
                )
            )

            unallocated -= quantity

            if unallocated <= 0:
                break

    SalesOrderAllocation.objects.bulk_create(new_allocations, batch_size=250)

@transaction.atomic
def allocate_serial_numbers(
    self,
    line_item: 'SalesOrderLineItem',
    quantity: int,
    serial_numbers: str,
    shipment: Optional['SalesOrderShipment'] = None,
) -> list['SalesOrderAllocation']:
    """Allocate stock items against this SalesOrder, by serial number.

    Arguments:
        line_item: The SalesOrderLineItem to allocate against
        quantity: The number of serial numbers expected
        serial_numbers: A string of serial numbers to allocate (e.g. "1,2,3-5")
        shipment: Optional shipment to assign the allocations to

    Raises:
        ValidationError: If the line item does not belong to this order,
            the serial numbers cannot be parsed, or any of the requested
            serial numbers do not exist or are unavailable for allocation.
    """
    if line_item.order != self:
        raise ValidationError(_('Line item is not associated with this order'))

    part = line_item.part

    serials = InvenTree.helpers.extract_serial_numbers(
        serial_numbers, quantity, part.get_latest_serial_number(), part=part
    )

    serials = [str(serial).strip() for serial in serials]

    serials_not_exist = set()
    serials_unavailable = set()
    stock_items_to_allocate = []

    # Bulk-fetch every candidate StockItem in a single query, keyed by serial,
    # rather than querying once per requested serial number
    candidate_items = {}

    for item in stock.models.StockItem.objects.filter(
        part=part, serial__in=serials, quantity=1
    ):
        candidate_items.setdefault(item.serial, item)

    for serial in serials:
        stock_item = candidate_items.get(serial)

        if stock_item is None:
            serials_not_exist.add(serial)
            continue

        if get_global_setting('SALESORDER_BLOCK_INCOMPLETE_ITEM_TESTS'):
            if (
                stock_item.hasRequiredTests()
                and not stock_item.passedAllRequiredTests()
            ):
                serials_unavailable.add(serial)
                continue

        if not stock_item.in_stock:
            serials_unavailable.add(serial)
            continue

        # Lock the StockItem row, so that concurrent allocation requests are
        # serialized against each other, and re-validate the unallocated
        # quantity against the now-current (and now-locked) state
        if not stock_item.lock_quantity():
            serials_unavailable.add(serial)
            continue

        if stock_item.unallocated_quantity() < 1:
            serials_unavailable.add(serial)
            continue

        # At this point, the serial number is valid, and can be added to the list
        stock_items_to_allocate.append(stock_item)

    if len(serials_not_exist) > 0:
        error_msg = _('No match found for the following serial numbers')
        error_msg += ': '
        error_msg += ','.join(sorted(serials_not_exist))

        raise ValidationError({'serial_numbers': error_msg})

    if len(serials_unavailable) > 0:
        error_msg = _('The following serial numbers are unavailable')
        error_msg += ': '
        error_msg += ','.join(sorted(serials_unavailable))

        raise ValidationError({'serial_numbers': error_msg})

    allocations = [
        SalesOrderAllocation(
            line=line_item, item=stock_item, quantity=1, shipment=shipment
        )
        for stock_item in stock_items_to_allocate
    ]

    SalesOrderAllocation.objects.bulk_create(allocations, batch_size=250)

    return allocations

def is_completed(self) -> bool:
    """Check if this order is "shipped" (all line items delivered).

    Note: Any "virtual" parts are ignored in this calculation.
    """
    lines = self.lines.all().filter(part__virtual=False)

    return all(line.is_completed() for line in lines)

def can_complete(
    self, raise_error: bool = False, allow_incomplete_lines: bool = False
) -> bool:
    """Test if this SalesOrder can be completed.

    Arguments:
        raise_error: If True, raise ValidationError if the order cannot be completed
        allow_incomplete_lines: If True, allow incomplete line items when completing the order

    Raises:
        ValidationError: If the order cannot be completed, and raise_error is True
    """
    try:
        if self.status == SalesOrderStatus.COMPLETE.value:
            raise ValidationError(_('Order is already complete'))

        if self.status == SalesOrderStatus.CANCELLED.value:
            raise ValidationError(_('Order is already cancelled'))

        # Only an open order can be marked as shipped
        if self.is_open and not self.is_completed:
            raise ValidationError(_('Only an open order can be marked as complete'))

        if self.pending_shipment_count > 0:
            raise ValidationError(
                _('Order cannot be completed as there are incomplete shipments')
            )

        if self.pending_allocation_count > 0:
            raise ValidationError(
                _('Order cannot be completed as there are incomplete allocations')
            )

        if not allow_incomplete_lines:
            pending_lines = self.pending_line_items().exclude(part__virtual=True)

            if pending_lines.count() > 0:
                raise ValidationError(
                    _(
                        'Order cannot be completed as there are incomplete line items'
                    )
                )

    except ValidationError as e:
        if raise_error:
            raise e
        else:
            return False

    return True

# region fsm
@deprecated("Use 'issue_order' instead", version='1.5.0')
def place_order(self):
    """Deprecated version of 'issue_order'."""
    return self.issue_order()

@inventree_transition(
    field=status,
    source=[SalesOrderStatus.PENDING, SalesOrderStatus.ON_HOLD],
    target=SalesOrderStatus.IN_PROGRESS,
    event=SalesOrderEvents.ISSUED,
)
def issue_order(self):
    """Transition this SalesOrder to IN_PROGRESS status.

    The order must currently be PENDING or ON_HOLD.
    """
    self.issue_date = InvenTree.helpers.current_date()

    notify_responsible(
        self,
        SalesOrder,
        exclude=self.created_by,
        content=InvenTreeNotificationBodies.NewOrder,
        extra_users=self.subscribed_users(),
    )

@property
@deprecated(Deprecations.CAN_PROCEED, version='1.5.0')
def can_issue(self) -> bool:
    """Return True if this order can be issued."""
    return can_proceed(self.issue_order)

@inventree_transition(
    field=status,
    source=[SalesOrderStatus.PENDING, SalesOrderStatus.IN_PROGRESS],
    target=SalesOrderStatus.ON_HOLD,
    event=SalesOrderEvents.HOLD,
)
def hold_order(self):
    """Transition this SalesOrder to ON_HOLD status.

    The order must currently be PENDING or IN_PROGRESS.
    """

@property
@deprecated(Deprecations.CAN_PROCEED, version='1.5.0')
def can_hold(self) -> bool:
    """Return True if this order can be placed on hold."""
    return can_proceed(self.hold_order)

def _ship_complete_action(self, user=None, **kwargs) -> SalesOrderStatus:
    """Shared logic for ship_order and complete_order.

    Returns the target state (SHIPPED or COMPLETE) based on global settings
    and the current order state.

    Raises:
        TransitionNotAllowed: if business-logic preconditions are not met.
    """
    if not self.can_complete(**kwargs):
        raise ValidationError('Order cannot be shipped or completed at this time')

    bypass_shipped = InvenTree.helpers.str2bool(
        get_global_setting('SALESORDER_SHIP_COMPLETE')
    )

    for line in self.lines.all():
        if line.part and line.part.virtual and line.shipped != line.quantity:
            line.shipped = line.quantity
            line.save()

        if line.part:
            line.part.schedule_pricing_update(create=True)

    if self.shipment_date is None:
        self.shipped_by = user
        self.shipment_date = InvenTree.helpers.current_date()

    trigger_event(SalesOrderEvents.COMPLETED, id=self.pk)

    if bypass_shipped or self.status == SalesOrderStatus.SHIPPED:
        return SalesOrderStatus.COMPLETE
    else:
        return SalesOrderStatus.SHIPPED

@inventree_transition(
    field=status,
    source=[
        SalesOrderStatus.PENDING,
        SalesOrderStatus.IN_PROGRESS,
        SalesOrderStatus.ON_HOLD,
        SalesOrderStatus.SHIPPED,
    ],
    target=RETURN_VALUE(SalesOrderStatus.SHIPPED, SalesOrderStatus.COMPLETE),
)
def ship_order(self, user=None, **kwargs):
    """Attempt to ship or complete this SalesOrder.

    The order must currently be PENDING, IN_PROGRESS, ON_HOLD, or already SHIPPED.
    Depending on global settings, the order will transition to SHIPPED or COMPLETE.
    """
    return self._ship_complete_action(user=user, **kwargs)

@inventree_transition(
    field=status,
    source=[
        SalesOrderStatus.PENDING,
        SalesOrderStatus.IN_PROGRESS,
        SalesOrderStatus.ON_HOLD,
        SalesOrderStatus.SHIPPED,
    ],
    target=RETURN_VALUE(SalesOrderStatus.SHIPPED, SalesOrderStatus.COMPLETE),
)
def complete_order(self, user=None, **kwargs):
    """Attempt to complete this SalesOrder.

    The order must currently be IN_PROGRESS, ON_HOLD, or SHIPPED.
    Depending on global settings, the order will transition to SHIPPED or COMPLETE.
    """
    return self._ship_complete_action(user=user, **kwargs)

@inventree_transition(
    field=status,
    source=[
        SalesOrderStatus.PENDING,
        SalesOrderStatus.ON_HOLD,
        SalesOrderStatus.IN_PROGRESS,
        SalesOrderStatus.SHIPPED,
    ],
    target=SalesOrderStatus.CANCELLED,
    event=SalesOrderEvents.CANCELLED,
)
def cancel_order(self):
    """Transition this SalesOrder to CANCELLED status.

    Deletes all pending stock allocations.
    """
    for line in self.lines.all():
        for allocation in line.allocations.all():
            allocation.delete()

    notify_responsible(
        self,
        SalesOrder,
        exclude=self.created_by,
        content=InvenTreeNotificationBodies.OrderCanceled,
        extra_users=self.subscribed_users(),
    )

@property
@deprecated(Deprecations.CAN_PROCEED, version='1.5.0')
def can_cancel(self) -> bool:
    """Return True if this order can be cancelled."""
    return can_proceed(self.cancel_order)

# endregion fsm

