    return post('/stock/location/', {'name': name or uniq('loc'), 'parent': parent})[
        'pk'
    ]


def part(**kw):
    body = {
        'name': uniq('part'),
        'description': 'race test',
        'category': category(),
        'component': True,
        'salable': True,
        'purchaseable': True,
        'active': True,
    }
    body.update(kw)
    return post('/part/', body)['pk']


