    ]
    if issue:
        ok(call('POST', f'/order/so/{so}/issue/', {}))
    return so, line


def so_ref():
    return f'SO-{next(_n):06d}'


def po_ref():
    return f'PO-{next(_n):06d}'


def bo_ref():
    return f'BO-{next(_n):06d}'


def shipment(so, ref=None):
    return post('/order/so/shipment/', {'order': so, 'reference': ref or uniq('sh')})[
        'pk'
    ]


def wait_tasks(timeout=60):
    """Wait until the background queue is drained."""
    import subprocess

    end = time.time() + timeout
    while time.time() < end:
        out = subprocess.run(
            [
                'docker', 'exec', 'inv-race-pg', 'psql', '-U', 'inv', '-d', 'inv',
                '-Atc', 'select count(*) from django_q_ormq',
            ],
            capture_output=True,
            text=True,
        ).stdout.strip()
        if out == '0':
            time.sleep(0.5)
            return True
        time.sleep(0.5)
    return False


def sql(q):
    import subprocess

    return subprocess.run(
        ['docker', 'exec', 'inv-race-pg', 'psql', '-U', 'inv', '-d', 'inv', '-Atc', q],
        capture_output=True,
        text=True,
    ).stdout.strip()

