"""Tiny helper library for firing overlapping requests at a local InvenTree."""

import itertools
import threading
import time

import requests

BASE = 'http://127.0.0.1:8765/api'
AUTH = ('admin', 'inventree123')
_tok = None
_n = itertools.count(int(time.time()) % 100000 * 100)


def token():
    global _tok
    if not _tok:
        _tok = requests.get(f'{BASE}/user/token/', auth=AUTH).json()['token']
    return _tok


def call(method, path, body=None, params=None):
    r = requests.request(
        method,
        f'{BASE}{path}',
        json=body,
        params=params,
        headers={'Authorization': f'Token {token()}'},
        timeout=120,
    )
    try:
        data = r.json()
    except Exception:
        data = r.text[:300]
    return r.status_code, data


def ok(res, expect=(200, 201)):
    code, data = res
    if code not in expect:
        raise RuntimeError(f'unexpected {code}: {str(data)[:500]}')
    return data


def get(path, **params):
    return ok(call('GET', path, params=params))


def post(path, body=None):
    return ok(call('POST', path, body or {}))


def patch(path, body):
    return ok(call('PATCH', path, body))


def uniq(prefix):
    return f'{prefix}-{next(_n)}'


def race(*fns, stagger=0.0):
    """Run the callables at the same instant (optionally staggered), return results in order."""
    barrier = threading.Barrier(len(fns))
    out = [None] * len(fns)

    def run(i, fn):
        barrier.wait()
        if stagger:
            time.sleep(i * stagger)
        try:
            out[i] = fn()
        except Exception as exc:  # noqa
            out[i] = ('EXC', repr(exc)[:300])

    threads = [threading.Thread(target=run, args=(i, f)) for i, f in enumerate(fns)]
    [t.start() for t in threads]
    [t.join() for t in threads]
    return out


# ---- fixtures -------------------------------------------------------------
_cache = {}


def category():
    if 'cat' not in _cache:
        _cache['cat'] = post('/part/category/', {'name': uniq('cat')})['pk']
    return _cache['cat']


def location(name=None, parent=None):
    return post('/stock/location/', {'name': name or uniq('loc'), 'parent': parent})[
        'pk'
    ]


def part(**kw):
    body = {
        'name': uniq('part'),
        'description': 'race test',
        'category': category(),
        'component': True,
        'salable': True,
        'purchaseable': True,
        'active': True,
    }
    body.update(kw)
    return post('/part/', body)['pk']


def stock(part_id, qty, loc, **kw):
    body = {'part': part_id, 'quantity': qty, 'location': loc}
    body.update(kw)
    res = post('/stock/', body)
    return res[0]['pk'] if isinstance(res, list) else res['pk']


def item(pk):
    return get(f'/stock/{pk}/')


def company(**kw):
    body = {'name': uniq('co'), 'is_supplier': True, 'is_customer': True}
    body.update(kw)
    return post('/company/', body)['pk']


def sales_order(customer, part_id, qty, issue=True):
    so = post('/order/so/', {'customer': customer, 'reference': so_ref()})['pk']
    line = post('/order/so-line/', {'order': so, 'part': part_id, 'quantity': qty})[
        'pk'
    ]
    if issue:
        ok(call('POST', f'/order/so/{so}/issue/', {}))
    return so, line


def so_ref():
    return f'SO-{next(_n):06d}'


def po_ref():
    return f'PO-{next(_n):06d}'


def bo_ref():
    return f'BO-{next(_n):06d}'


def shipment(so, ref=None):
    return post('/order/so/shipment/', {'order': so, 'reference': ref or uniq('sh')})[
        'pk'
    ]


def wait_tasks(timeout=60):
    """Wait until the background queue is drained."""
    import subprocess

    end = time.time() + timeout
    while time.time() < end:
        out = subprocess.run(
            [
                'docker', 'exec', 'inv-race-pg', 'psql', '-U', 'inv', '-d', 'inv',
                '-Atc', 'select count(*) from django_q_ormq',
            ],
            capture_output=True,
            text=True,
        ).stdout.strip()
        if out == '0':
            time.sleep(0.5)
            return True
        time.sleep(0.5)
    return False


def sql(q):
    import subprocess

    return subprocess.run(
        ['docker', 'exec', 'inv-race-pg', 'psql', '-U', 'inv', '-d', 'inv', '-Atc', q],
        capture_output=True,
        text=True,
    ).stdout.strip()

